use vstd::prelude::*;

verus! {
    /// Returns the longest character sequence in `strings`, breaking ties
    /// by choosing the earliest occurrence.  If `strings` is empty, returns `None`.
    fn longest(strings: Vec<Vec<char>>) -> (result: Option<Vec<char>>)
        ensures
            // If the input is empty, we return None.
            strings.len() == 0 ==> result.is_None(),
            // Otherwise we return Some(res) where
            //   * res equals one of the input sequences at some index `idx`,
            //   * no sequence in the input is longer than `res`,
            //   * every index before `idx` has strictly smaller length than `res`.
            strings.len() > 0  ==> result.is_Some_with(|res: Vec<char>|
                exists |idx: usize|
                    idx < strings.len() &&
                    // exact content match
                    res == strings[idx] &&
                    // res is a maximum‐length sequence
                    (forall |j: usize| j < strings.len() ==> strings[j].len() <= res.len()) &&
                    // earliest occurrence of that maximum length
                    (forall |j: usize| j < idx             ==> strings[j].len() <  res.len())
            ),
    {
        // Special‐case the empty list
        if strings.len() == 0 {
            return None;
        }

        let n = strings.len();
        // Initialize best_idx to 0 and best_len to the length of the first sequence
        let mut best_idx: usize = 0;
        let mut best_len: usize = strings[0].len();
        // Scan i from 1..n
        let mut i: usize = 1;
        while i < n
            invariant
                // bounds
                i <= n,
                best_idx < i,
                // correctness of best_len
                best_len == strings[best_idx].len(),
                // best_len is the maximum length seen so far in [0..i)
                forall(|j: usize| j < i ==> strings[j].len() <= best_len),
                // best_idx is the earliest index achieving best_len
                forall(|j: usize| j < best_idx ==> strings[j].len() < best_len),
            decreases n - i,
        {
            let cur_len = strings[i].len();
            if cur_len > best_len {
                best_len = cur_len;
                best_idx = i;
            }
            i = i + 1;
        }

        // By the invariants we know best_idx < n and best_len is maximal and earliest.
        let answer = strings[best_idx].clone();
        Some(answer)
    }
}

